// ============================================================
// North America, 1640–2017, by theme: hymnody and gospel music, mission agencies, seminaries and
// colleges, immigrant and Asian American evangelicals, parachurch organisations and recent landmarks.
// Merged into the main dataset by data.js. Every event carries its sources.
// ============================================================
import { w } from "./sources.js";

function ev(era, year, figure, title, description, titleEs, descriptionEs, sources) {
  return { era, year, figure, title, description, es: { title: titleEs, description: descriptionEs }, sources };
}
const wiki = (title, slug) => w(`Wikipedia, "${title}"`, "https://en.wikipedia.org/wiki/" + (slug || title.replace(/ /g, "_")));
const loc = (id, name, place, country, countryEs, region, regionEs, lat, lng, events, placeEs) =>
  ({ id, name, modernName: `${place}, ${country}`, region, lat, lng, significance: "minor", zone: "north",
     es: { name, modernName: `${placeEs || place}, ${countryEs}`, region: regionEs || region }, events });
const US = (id, name, place, region, lat, lng, events, placeEs) =>
  loc(id, name, place, "USA", "EE. UU.", region, region, lat, lng, events, placeEs);

